Use a circular buffer with overflow rejection. The invariant is `0 <= size_ <= 17`, with `head_` pointing to the next element to pop and logical element `i` stored at `(head_ + i) % 17`. Push writes at `(head_ + size_) % 17`; a full push or empty pop leaves the queue unchanged.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) return false;
        data_[(head_ + size_) % capacity] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

void check(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message);
}

int main() {
    try {
        BoundedFIFO q;
        check(!q.pop().has_value(), "Initial empty pop failed");

        // Fill all 17 slots and reject overflow.
        for (int i = 0; i < 17; ++i)
            check(q.push(i), "Fill failed");
        check(q.size() == 17, "Incorrect full size");
        check(!q.push(99), "Overflow was accepted");
        check(q.size() == 17, "Overflow changed size");

        // Drain and verify FIFO order and empty rejection.
        for (int i = 0; i < 17; ++i)
            check(q.pop() == std::optional<int>{i}, "Drain order failed");
        check(q.empty(), "Drain did not empty queue");
        check(!q.pop().has_value(), "Empty pop was accepted");

        // Keep two elements, then wrap writes around the array.
        for (int i = 0; i < 12; ++i)
            check(q.push(i), "Wrap setup push failed");
        for (int i = 0; i < 10; ++i)
            check(q.pop() == std::optional<int>{i}, "Wrap setup pop failed");
        for (int i = 12; i < 27; ++i)
            check(q.push(i), "Wrapped push failed");

        check(q.size() == 17, "Incorrect wrapped size");
        check(!q.push(99), "Wrapped overflow was accepted");
        for (int i = 10; i < 27; ++i)
            check(q.pop() == std::optional<int>{i}, "Wrapped FIFO order failed");
        check(q.empty(), "Wrapped drain failed");
        check(!q.pop().has_value(), "Final empty pop failed");

        std::cout << "All tests passed\n";
        return 0;
    } catch (const std::exception& e) {
        std::cerr << "Test failed: " << e.what() << '\n';
        return 1;
    }
}
```

Save as `fifo.cpp`, compile with `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo`, and run the resulting executable. Push and pop take constant time; this implementation is for single-threaded use.
